<?php
require __DIR__.'/../includes/app.php';session_start_safe();$setupToken=getenv('ADMIN_SETUP_TOKEN')?:'';if(!preg_match('/^[a-f0-9]{64}$/i',$setupToken)){http_response_code(403);exit('Setup dinonaktifkan. Atur ADMIN_SETUP_TOKEN berupa 64 karakter hex acak pada server untuk membuat akun pertama.');}$error='';$ready=false;$locked=false;
try {$ready=(bool)db()->query('SELECT id FROM profile WHERE id=1')->fetch();$locked=(int)db()->query('SELECT COUNT(*) FROM admins')->fetchColumn()>0;} catch(Throwable $e){$error='Jalankan MySQL, impor database/portfolio_alfi.sql, dan cek config.php terlebih dahulu.';}
if($_SERVER['REQUEST_METHOD']==='POST' && $ready && !$locked){check_csrf();if(!is_string($_POST['setup_token']??null)||!hash_equals($setupToken,$_POST['setup_token'])){http_response_code(403);exit('Token setup tidak valid.');}$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');
 if(!preg_match('/^[A-Za-z0-9_.-]{3,100}$/',$username))$error='Username 3–100 karakter: huruf, angka, titik, garis bawah, atau tanda minus.';
 elseif(strlen($password)<10 || strlen($password)>72)$error='Password harus 10–72 karakter.';
 elseif($password!==($_POST['confirm']??''))$error='Konfirmasi password berbeda.';
 else try{db()->beginTransaction();db()->query('SELECT id FROM profile WHERE id=1 FOR UPDATE');if((int)db()->query('SELECT COUNT(*) FROM admins')->fetchColumn()>0)throw new RuntimeException('locked');$q=db()->prepare('INSERT INTO admins (username,password_hash) VALUES (?,?)');$q->execute([$username,password_hash($password,PASSWORD_DEFAULT)]);db()->commit();redirect('login.php?created=1');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error='Akun tidak bisa dibuat. Jika sudah ada admin, masuk melalui halaman login.';}
}
?><!doctype html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Setup Admin</title><link rel="stylesheet" href="../assets/style.css?v=sky-20261020"><link rel="stylesheet" href="../assets/admin.css?v=admin-studio-20261025"><script defer src="../assets/admin.js?v=admin-studio-20261025"></script></head><body class="auth-body"><div class="auth-layout"><aside class="auth-story"><span class="auth-monogram">MA</span><span class="eyebrow">ALFI / CONTENT STUDIO</span><h2>Portofolio,<br>tetap terurus.</h2><p>Satu ruang untuk memperbarui karya, pengalaman, dan pencapaianmu.</p><div class="auth-topics"><span>Projects</span><span>Experience</span><span>Certificates</span></div></aside><main class="auth-card panel"><p class="eyebrow">ONE-TIME SETUP</p><h1><?= $locked?'Admin sudah siap.':'Buat akun admin.'?></h1><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><?php if($locked):?><p>Setup otomatis terkunci setelah akun pertama dibuat.</p><a class="button" href="login.php">Ke halaman login ↗</a><?php elseif($ready):?><p>Tentukan username dan password kamu sendiri.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Token setup<input name="setup_token" type="password" autocomplete="off" required></label><label>Username<input name="username" required minlength="3" maxlength="100" autocomplete="username"></label><label>Password<input name="password" type="password" required minlength="10" maxlength="72" autocomplete="new-password"></label><label>Konfirmasi password<input name="confirm" type="password" required minlength="10" maxlength="72" autocomplete="new-password"></label><button class="button">Buat akun ↗</button></form><?php endif;?><p><a href="../">← Kembali ke website</a></p></main></div></body></html>
